package org.ssssssss.magicapi.iot.transport.websocket; import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.Bean;import org.ssssssss.magicapi.iot.core.spi.*;import org.ssssssss.magicapi.iot.plugin.api.*;import java.time.Duration;import java.util.Map;@AutoConfiguration @EnableConfigurationProperties(WebSocketTransportProperties.class) @ConditionalOnProperty(prefix="iot.transports.websocket",name="enabled",havingValue="true") public class WebSocketTransportAutoConfiguration{@Bean(destroyMethod="close")NettyWebSocketTransportProvider webSocketTransportProvider(WebSocketTransportProperties p){return new NettyWebSocketTransportProvider(p);}@Bean ProviderHealthIndicator webSocketTransportHealth(NettyWebSocketTransportProvider t){return new ProbeProviderHealthIndicator("transport","websocket",Duration.ofSeconds(5),Duration.ofSeconds(1),()->t.isRunning()?ProbeProviderHealthIndicator.up(Map.of("snapshot",t.snapshot())):new PluginHealth(PluginHealth.Status.DOWN,"WebSocket transport is not listening",Map.of()));}}
